body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: transparent;
  color: #111827;
}

.cash-app {
  width: 100%;
  box-sizing: border-box;
  padding: 14px;
  background: #ffffff;
  border: 1px solid #d0d5dd;
  border-radius: 10px;
}

.top {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  margin-bottom: 14px;
}

.eyebrow {
  color: #667085;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

h2 {
  margin: 3px 0 0;
  font-size: 18px;
}

.total-box {
  min-width: 150px;
  padding: 10px 12px;
  border-radius: 8px;
  background: #111827;
  color: white;
  text-align: right;
}

.total-box span {
  display: block;
  font-size: 10px;
  color: #d1d5db;
  text-transform: uppercase;
}

.total-box strong {
  display: block;
  margin-top: 3px;
  font-size: 18px;
}

.denoms {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 9px;
}

.denom {
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  padding: 9px;
  background: #f9fafb;
}

.value {
  font-size: 15px;
  font-weight: 900;
}

.amount {
  color: #667085;
  font-size: 11px;
  margin-top: 2px;
}

.controls {
  display: grid;
  grid-template-columns: 30px 1fr 30px;
  gap: 5px;
  margin-top: 8px;
}

button {
  border: 0;
  border-radius: 6px;
  background: #111827;
  color: white;
  font-weight: 900;
  cursor: pointer;
}

input {
  width: 100%;
  height: 30px;
  border: 1px solid #d0d5dd;
  border-radius: 6px;
  text-align: center;
  font-weight: 800;
  box-sizing: border-box;
}

@media (max-width: 700px) {
  .denoms {
    grid-template-columns: repeat(3, 1fr);
  }
}

