const DEFAULT_LINES = [500, 200, 100, 50, 20, 10, 5, 2, 1, 0.5, 0.2, 0.1, 0.05, 0.02, 0.01];
function normalizeLines(lines) {
  const existing = Array.isArray(lines) && lines.length ? lines : DEFAULT_LINES.map(value => ({
    denominationValue: value,
    quantity: 0,
    amount: 0
  }));
  return existing.map(row => {
    const denominationValue = Number(row.denominationValue || row.value || 0);
    const quantity = Number(row.quantity || 0);
    return {
      denominationValue,
      quantity,
      amount: Number((denominationValue * quantity).toFixed(2))
    };
  });
}
function total(lines) {
  return Number(lines.reduce((sum, row) => sum + Number(row.amount || 0), 0).toFixed(2));
}
function render(model = {}) {
  const title = model.title || "Cash Operation";
  const currency = model.currency || "EUR";
  const lines = normalizeLines(model.lines);
  document.getElementById("title").innerText = title;
  document.getElementById("total").innerText = `${total(lines).toFixed(2)} ${currency}`;
  document.getElementById("denoms").innerHTML = lines.map((row, index) => `
    <div class="denom">
      <div class="value">${row.denominationValue.toFixed(row.denominationValue < 1 ? 2 : 0)} ${currency}</div>
      <div class="amount">${row.amount.toFixed(2)} ${currency}</div>
      <div class="controls">
        <button data-action="minus" data-index="${index}">-</button>
        <input data-index="${index}" value="${row.quantity}" inputmode="numeric" />
        <button data-action="plus" data-index="${index}">+</button>
      </div>
    </div>
  `).join("");
  bind(lines, currency);
}
function update(lines) {
  const normalized = normalizeLines(lines);
  const nextTotal = total(normalized);
  appsmith.updateModel({
    lines: normalized,
    total: nextTotal
  });
  appsmith.triggerEvent("onCashCountChange");
  render({
    ...(appsmith.model || {}),
    lines: normalized,
    total: nextTotal
  });
}
function bind(lines) {
  document.querySelectorAll("button[data-action]").forEach(button => {
    button.onclick = () => {
      const index = Number(button.dataset.index);
      const action = button.dataset.action;
      const next = [...lines];
      const currentQty = Number(next[index].quantity || 0);
      next[index].quantity = action === "plus" ? currentQty + 1 : Math.max(0, currentQty - 1);
      update(next);
    };
  });
  document.querySelectorAll("input[data-index]").forEach(input => {
    input.onchange = () => {
      const index = Number(input.dataset.index);
      const next = [...lines];
      next[index].quantity = Math.max(0, Number(input.value || 0));
      update(next);
    };
  });
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

